#!/usr/bin/env python3
"""Build a standalone executable simulation of the six questions and 12 T4 screens."""
from __future__ import annotations

import argparse
import hashlib
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=ROOT / "simulation/T4_12_ECRANS_EXECUTABLE.html")
    args = parser.parse_args()
    questions_path = ROOT / "form/questions_T4.json"
    flow_path = ROOT / "config/T4_CAPTURE_FLOW_V1_0_0.json"
    questions = json.loads(questions_path.read_text(encoding="utf-8"))
    flow = json.loads(flow_path.read_text(encoding="utf-8"))
    if len(questions["fields"]) != 6 or len(flow["screens"]) != 12:
        raise SystemExit("T4 simulation requires exactly six questions and twelve screens")
    q_json = json.dumps(questions, ensure_ascii=False).replace("</", "<\\/")
    f_json = json.dumps(flow, ensure_ascii=False).replace("</", "<\\/")
    template = r'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>T4 — 6 questions et 12 écrans exécutables</title>
<style>
:root{--ink:#17120d;--cream:#f4ede1;--paper:#fffaf2;--warm:#b85f35;--gold:#d6a35f;--dark:#111315;--muted:#756b60;--ok:#4f7655;--danger:#9c4738}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 10%,#3c261d 0,#17191b 36%,#080a0b 100%);color:var(--cream);font:15px/1.45 Inter,ui-sans-serif,system-ui,sans-serif;min-height:100vh}.shell{max-width:1180px;margin:auto;padding:22px;display:grid;grid-template-columns:270px minmax(320px,430px) minmax(260px,1fr);gap:22px;align-items:start}.panel{background:#151719e8;border:1px solid #40372f;border-radius:22px;box-shadow:0 26px 70px #0008}.side{padding:22px;position:sticky;top:22px}.eyebrow{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#e5b879;font-weight:800}.side h1{font:700 28px/1.02 Georgia,serif;margin:10px 0}.side p{color:#bcb2a7}.stat{display:flex;justify-content:space-between;border-top:1px solid #3a332d;padding:11px 0}.stat b{color:#f0c889}.routes{width:100%;background:#0e1011;color:#eee;border:1px solid #4c4239;border-radius:12px;padding:10px;margin:8px 0 16px}.nav{display:grid;grid-template-columns:1fr 1fr;gap:8px}.btn{border:0;border-radius:12px;padding:11px 13px;font-weight:800;cursor:pointer;background:#ead9c2;color:#21170e}.btn.primary{background:linear-gradient(135deg,#c56e40,#e7ac64);color:#1b1009}.btn.ghost{background:#292826;color:#e8dfd4;border:1px solid #4a433c}.btn:disabled{opacity:.35;cursor:not-allowed}.phone{padding:10px;background:#050606;border:1px solid #413a34;border-radius:36px;box-shadow:0 35px 75px #000a;min-height:760px}.screen{min-height:738px;border-radius:27px;overflow:hidden;position:relative;background:#18130f}.camera{position:absolute;inset:0;background:linear-gradient(155deg,#17100b 0,#72503c 38%,#291e19 70%,#100d0b 100%)}.camera:before{content:"";position:absolute;width:210px;height:410px;left:50%;top:18%;transform:translateX(-50%);border-radius:100px 100px 22px 22px;background:linear-gradient(#e7c0a277,#322018aa);filter:blur(2px)}.camera:after{content:"APERÇU CAMÉRA";position:absolute;inset:auto 0 45%;text-align:center;letter-spacing:.22em;font-size:10px;color:#fff9}.shade{position:absolute;inset:0;background:linear-gradient(#0004,#0001 38%,#000c)}.phone-ui{position:relative;z-index:2;min-height:738px;padding:26px 20px;display:flex;flex-direction:column}.topline{display:flex;justify-content:space-between;align-items:center;font-weight:800;font-size:12px;letter-spacing:.08em}.pill{padding:7px 10px;border-radius:999px;background:#17130fbb;border:1px solid #d8af775c}.progress{height:5px;background:#ffffff2a;border-radius:10px;margin:15px 0;overflow:hidden}.progress span{display:block;height:100%;background:linear-gradient(90deg,#d27743,#efc47d);border-radius:inherit}.sheet{margin-top:auto;background:#fffaf4;color:var(--ink);border-radius:24px;padding:22px;box-shadow:0 -20px 45px #0005}.sheet h2{font:800 30px/1 Georgia,serif;margin:5px 0 12px}.sheet p{margin:7px 0}.instruction{font-size:16px}.cols{display:grid;grid-template-columns:1fr;gap:10px;margin:14px 0}.list{padding:12px;border-radius:14px;background:#f2e9dd}.list.bad{background:#f5e2dd}.list b{display:block;font-size:11px;letter-spacing:.13em;text-transform:uppercase;margin-bottom:5px}.list ul{padding-left:17px;margin:4px 0}.list li{margin:4px 0}.note{padding:11px;border-left:3px solid var(--gold);background:#fff4e4;border-radius:4px 10px 10px 4px;font-size:13px}.recording{justify-content:space-between;text-align:center}.rec-dot{width:14px;height:14px;background:#e65340;border-radius:50%;box-shadow:0 0 0 7px #e653402c;display:inline-block;margin-right:8px}.timer{font:800 74px/1 ui-monospace,monospace;margin-top:170px;text-shadow:0 3px 18px #000}.prompt{font-size:19px;font-weight:900;letter-spacing:.06em;background:#16120ec9;border:1px solid #d7aa7180;padding:14px;border-radius:14px;margin:18px}.review-card{margin-top:auto;background:#fffaf4;color:var(--ink);border-radius:24px;padding:22px}.preview{height:285px;border-radius:18px;background:linear-gradient(145deg,#2b1d16,#87624c 48%,#1b1512);display:grid;place-items:center;color:#fff;font-weight:800;letter-spacing:.12em}.checks{list-style:none;padding:0}.checks li:before{content:"✓";color:var(--ok);font-weight:900;margin-right:9px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px}.form-screen{min-height:738px;background:linear-gradient(160deg,#f7efe3,#e6d3ba);color:var(--ink);padding:26px 22px;overflow:auto}.form-screen h2{font:800 31px/1.05 Georgia,serif}.field{margin:12px 0}.field label{font-weight:800;display:block;margin-bottom:5px}.field small{display:block;color:#695f55;margin-top:4px}.field input{width:100%;border:1px solid #b8a48d;border-radius:11px;padding:11px;background:#fffaf3;font:inherit}.field input:focus{outline:3px solid #d39a5c55;border-color:#a65c34}.error{color:#9d3024;font-weight:800;min-height:20px}.detail{padding:22px}.detail h2{font:700 25px/1.1 Georgia,serif}.code{background:#0b0c0d;border:1px solid #3b3834;color:#d8c9b6;border-radius:14px;padding:12px;max-height:330px;overflow:auto;font:12px/1.45 ui-monospace,monospace;white-space:pre-wrap}.binding{color:#c9b69e;border-bottom:1px solid #3a342e;padding:8px 0}.success{color:#a9d2ad}.hidden{display:none}@media(max-width:980px){.shell{grid-template-columns:230px minmax(320px,430px)}.detail{grid-column:1/-1}.side{position:static}}@media(max-width:700px){.shell{display:block;padding:10px}.side,.phone,.detail{margin-bottom:14px}.phone{min-height:auto}.screen,.form-screen,.phone-ui{min-height:690px}}
</style></head><body><main class="shell"><aside class="panel side"><div class="eyebrow">RESTAURATION‑T4</div><h1>Expérience client</h1><p>Simulation autonome reliée aux six questions et au contrat exécutable des douze écrans.</p><div class="stat"><span>Questions</span><b>6</b></div><div class="stat"><span>Scènes</span><b>4</b></div><div class="stat"><span>Écrans stables</span><b>12</b></div><label for="routes" class="eyebrow">Route</label><select id="routes" class="routes"></select><div class="nav"><button class="btn ghost" id="prev">← Précédent</button><button class="btn ghost" id="next">Suivant →</button></div><p id="sourceStatus" class="success"></p></aside><section class="phone"><div id="stage" class="screen"></div></section><aside class="panel detail"><div class="eyebrow">Contrat actif</div><h2 id="detailTitle">Six réponses commerçant</h2><div id="bindings"></div><h3>État JSON</h3><pre id="json" class="code"></pre></aside></main>
<script type="application/json" id="questions">__QUESTIONS__</script><script type="application/json" id="flow">__FLOW__</script>
<script>
const questions=JSON.parse(document.querySelector('#questions').textContent);const flow=JSON.parse(document.querySelector('#flow').textContent);const screens=flow.screens;let route=-1;let timer=null;const payload={};
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function init(){const select=$('#routes');select.innerHTML='<option value="-1">Questions commerçant</option>'+screens.map((s,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${s.scene_id} · ${s.state.replace(/^[A-C]_/, '')}</option>`).join('');select.onchange=()=>go(Number(select.value));$('#prev').onclick=()=>go(Math.max(-1,route-1));$('#next').onclick=()=>go(Math.min(screens.length-1,route+1));$('#sourceStatus').textContent='JSON intégré · 6/6 · 12/12';go(-1)}
function go(index){if(timer){clearInterval(timer);timer=null}route=index;$('#routes').value=String(route);$('#prev').disabled=route<0;$('#next').disabled=route>=screens.length-1;if(route<0)renderForm();else renderScreen(screens[route]);}
function renderForm(){const fields=questions.fields.map(f=>`<div class="field"><label for="f_${esc(f.id)}">${esc(f.question)}${f.required?' *':''}</label><input id="f_${esc(f.id)}" data-id="${esc(f.id)}" minlength="${f.minLength}" maxlength="${f.maxLength}" ${f.pattern?`pattern="${esc(f.pattern)}"`:''} value="${esc(payload[f.id]??'')}" placeholder="${esc(f.example??'')}"><small>${esc(f.helper??f.json_target)}</small></div>`).join('');$('#stage').className='form-screen';$('#stage').innerHTML=`<div class="eyebrow">Étape 1 · données vraies</div><h2>Six questions avant de filmer</h2><p>Cinq réponses sont requises. L'accroche reste facultative et ne doit jamais devenir un faux témoignage.</p>${fields}<div id="formError" class="error"></div><button id="start" class="btn primary" style="width:100%">OUVRIR LES 12 ÉCRANS</button>`;$('#start').onclick=()=>{let error='';questions.fields.forEach(f=>{const input=$(`#f_${f.id}`);const value=input.value.replace(/\s+/g,' ').trim();payload[f.id]=value;if(f.required&&!value)error=`Le champ « ${f.id} » est requis.`;if(value.length<f.minLength||value.length>f.maxLength)error=`Longueur invalide pour « ${f.id} ».`;if(f.pattern&&value&&!new RegExp(f.pattern).test(value))error=`Format invalide pour « ${f.id} ».`});$('#formError').textContent=error;if(!error){try{localStorage.setItem('t4_merchant_payload',JSON.stringify(payload))}catch(e){}go(0)}};detail('Questions commerçant',questions.fields.map(f=>[f.id,f.json_target]),{merchant_payload:payload,source:'form/questions_T4.json'})}
function renderScreen(s){$('#stage').className='screen';const r=s.resolved_text||{};const progress=(s.scene_index-1)/4*100;let body='';if(s.state==='A_GUIDE'){body=`<div class="camera"></div><div class="shade"></div><div class="phone-ui"><div class="topline"><span>${esc(r.scene_counter)}</span><span class="pill">${esc(r.duration)}</span></div><div class="progress"><span style="width:${progress+8}%"></span></div><div class="sheet"><div class="eyebrow">Guide de prise</div><h2>${esc(r.title)}</h2><p class="instruction">${esc(r.instruction)}</p><div class="cols"><div class="list"><b>À filmer</b><ul>${(r.film_list||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="list bad"><b>À éviter</b><ul>${(r.avoid_list||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div><p class="note">${esc(r.required_action||'')}</p><button class="btn primary action" style="width:100%">${esc(r.primary_action||'COMMENCER')}</button></div></div>`}else if(s.state==='B_RECORDING'){body=`<div class="camera"></div><div class="shade"></div><div class="phone-ui recording"><div class="topline"><span>${esc(r.scene_counter)}</span><span><i class="rec-dot"></i>ENREGISTREMENT</span></div><div><div id="timer" class="timer">0:00</div><div id="prompt" class="prompt">PRÊT À FILMER</div><div class="progress"><span id="recordProgress" style="width:0"></span></div><button id="record" class="btn primary">LANCER LA SIMULATION</button></div><p>Arrêt automatique · micro actif · vitesse 1,0×</p></div>`}else{body=`<div class="camera"></div><div class="shade"></div><div class="phone-ui"><div class="topline"><span>VALIDATION ${esc(s.scene_id)}</span><span class="pill">${esc(r.take_label)}</span></div><div class="review-card"><div class="preview">LECTURE IMAGE + SON</div><h2>${esc(r.review_question)}</h2><ul class="checks">${(r.review_checks||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="note">${esc(r.review_error)}</p><div class="actions"><button id="retake" class="btn ghost">${esc(r.redo_action)}</button><button id="accept" class="btn primary">${esc(r.positive_action)}</button></div></div></div>`}$('#stage').innerHTML=body;if(s.state==='A_GUIDE')$('.action').onclick=()=>go(route+1);if(s.state==='B_RECORDING')$('#record').onclick=()=>simulateRecording(s);if(s.state==='C_REVIEW'){$('#retake').onclick=()=>go(route-2);$('#accept').onclick=()=>go(Math.min(screens.length-1,route+1))}detail(s.screen_id,Object.entries(s.bindings||{}),s)}
function simulateRecording(s){const duration=s.capture_duration_ms;const started=Date.now();$('#record').disabled=true;timer=setInterval(()=>{const elapsed=Math.min(duration,Date.now()-started),seconds=elapsed/1000;$('#timer').textContent=`0:${String(Math.floor(seconds)).padStart(2,'0')}`;$('#recordProgress').style.width=`${elapsed/duration*100}%`;const prompts=s.resolved_text.prompt_timeline||[];const active=prompts.find(p=>elapsed>=p.from_ms&&elapsed<p.to_ms);$('#prompt').textContent=active?active.text:'FIN STABLE';if(elapsed>=duration){clearInterval(timer);timer=null;setTimeout(()=>go(route+1),250)}},80)}
function detail(title,bindings,data){$('#detailTitle').textContent=title;$('#bindings').innerHTML=bindings.map(([k,v])=>`<div class="binding"><b>${esc(k)}</b><br>${esc(v)}</div>`).join('');$('#json').textContent=JSON.stringify(data,null,2)}init();
</script></body></html>'''
    rendered = template.replace("__QUESTIONS__", q_json).replace("__FLOW__", f_json)
    provenance = f"<!-- generated from form/questions_T4.json sha256={digest(questions_path)} and config/T4_CAPTURE_FLOW_V1_0_0.json sha256={digest(flow_path)} -->\n"
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(provenance + rendered + "\n", encoding="utf-8")
    print(f"T4_SIMULATION_BUILT {args.output} 6 questions 12 screens")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
